--

CREATE FUNCTION nlpg.has_head(nlpg.word) RETURNS nlpg.word
    LANGUAGE sql
    AS $_$
    select
        m2
    from
        word m2
        join lexeme x2 on m2.lexeme = x2.id
        join lexeme x1 on $1.lexeme = x1.id
    where
        $1.string = m2.string
        and $1.head = m2.i
$_$;


--
-- Name: insert_annotations(integer); Type: FUNCTION; Schema: nlpg; Owner: -
--

CREATE FUNCTION nlpg.insert_annotations(integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql
    AS $_$
begin
    /* lemmas */
    raise info 'Inserting lemmas.';
        lemma,
        pos)
    select distinct
        lemma,
        pos
    from
        _textobj
    where
        type = 1
    except
    select distinct
        lemma,
        pos
    from
        lemma;

    /* Morphologies */
    raise info 'Inserting morphologies.';
        feats)
    select distinct
        i.morph
    from
        _textobj i
    where
        type = 1
    except
    select distinct
        feats
    from
        nlpg.morph;

    /* Lexemes */
    raise info 'Inserting lexemes.';
        norm,
        lemma,
        morph)
    select distinct
        i.norm,
        l.id,
        m.id
    from
        _textobj i
        join lemma l on l.lemma = i.lemma
        join morph m on m.feats = i.morph
    where
        i.type = 1
    except
    select distinct
        x.norm,
        x.lemma,
        x.morph
    from
        lexeme x;

    /* Sentences */
    raise info 'Inserting sentences.';
        string,
        i)
    select
        i.text_id,
        i.sent_i
    from
        _textobj i
    where
        i.type = -1;

    /* Update indexes */
    raise info 'Updating indexes.';
    analyze sent;
    analyze lemma;
    analyze lexeme;
    analyze _textobj;

    /* Words */
    raise info 'Inserting words.';
        sent,
        i,
        idx,
        len,
        s,
        tspace,
        dep,
        lexeme,
        head)
    select
        s.id,
        i.i,
        i.idx,
        i.len,
        i.s,
        i.tspace,
        i.dep,
        x.id,
        i.head
    from
        _textobj i
        join lemma l on l.lemma = i.lemma
            and l.pos = i.pos
        join morph m on m.feats = i.morph
        join lexeme x on x.norm = i.norm
            and l.id = x.lemma
            and x.morph = m.id
        join sent s on s.string = i.text_id
            and s.i = i.sent_i
    where
        i.type = 1;

    /* Non-word tokens */
    raise info 'Inserting non-words tokens...';
        sent,
        i,
        idx,
        len,
        s,
        tspace)
    select
        s.id,
        i.i,
        i.idx,
        i.len,
        i.s,
        i.tspace
    from
        _textobj i
        join sent s on s.string = i.text_id
            and s.i = i.sent_i
    where
        i.type = 0;
    raise info 'Annotations successfully inserted!';

    /* Truncate table if parameter is 1. */
    if $1 = 1 then
        truncate _textobj;
    end if;
end;
$_$;


--
-- Name: tokenandtag(integer); Type: FUNCTION; Schema: nlpg; Owner: -
--

CREATE FUNCTION nlpg.tokenandtag(sid integer) RETURNS TABLE(s text, tspace integer, lemma text, pos text, idxtext integer, idxxml integer)
    LANGUAGE sql
    AS $_$
    with x as (
        select
            token.s,
            token.tspace,
            '' as lemma,
            '' as pos,
            token.idx as idxtext,
            token.idx as idxxml
        from
            only nlpg.token
            join nlpg.sent on sent.id = token.sent
        where
            sent.string = $1
        union
        select
            word.s,
            word.tspace,
            lemma.lemma,
            pos.name as pos,
            word.idx as idxtext,
            word.idx as idxxml
        from
            nlpg.word
            join nlpg.sent on sent.id = word.sent
            join nlpg.lexeme on lexeme.id = word.lexeme
            join nlpg.lemma on lemma.id = lexeme.lemma
            join nlpg.pos on pos.id = lemma.pos
        where
            sent.string = $1
        union
        select
            s,
            0 as tspace,
            '' as lemma,
            '' as pos,
            idxtext,
            idxxml
        from
            nlpg.xtag
        where
            sid = $1
)
    select
        *
    from
        x
    order by
        idxtext,
        idxxml
$_$;


